WITH Src AS (SELECT *, CASE WHEN job_title IN ('Intern', 'Designer') THEN 'Tier 1' ELSE 'Other' END job_title_group FROM employees WHERE NOT (dept_id IN (22, 27, 30, 35) AND (job_title IS NULL OR manager_id = 10))), agg AS (SELECT level, job_title, ROUND(STDDEV(salary), 2) stddev_salary, COUNT(CASE WHEN level = 'L4' THEN 1 END) l4_count FROM Src GROUP BY level, job_title) SELECT level, job_title, stddev_salary, l4_count FROM agg
